param([Parameter(Mandatory=$true)][string]$HeaderPath,
 [Parameter(Mandatory=$true)][string]$ValidatorPath,
 [Parameter(Mandatory=$true)][string]$TestPath)
$ErrorActionPreference='Stop'
function A([bool]$x,[string]$m){if(-not $x){throw $m}}
function O([string]$t,[string[]]$v,[string]$n){$p=-1;foreach($x in $v){$q=$t.IndexOf($x,$p+1);A ($q-gt$p) "$n order $x";$p=$q}}
function V([string]$h,[string]$s,[string]$t){
 $legacy=@(
 '#define IOCTL_HYPERVISOR_LOAD    ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_UNLOAD  ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_HOOK    ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_UNHOOK  ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_STATUS  ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x804, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_PROBE   ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x805, METHOD_BUFFERED, FILE_ANY_ACCESS))',
 '#define IOCTL_HYPERVISOR_LAUNCH_PROBE ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x806, METHOD_BUFFERED, FILE_ANY_ACCESS))')
 $values=@('0x80002000','0x80002004','0x80002008','0x8000200C','0x80002010','0x80002014','0x80002018')
 for($i=0;$i-lt$legacy.Count;$i++){A ($h.Contains($legacy[$i])-and$t.Contains($values[$i])) "legacy IOCTL $i"}
 A ($h.Contains('#define IOCTL_HYPERVISOR_PERSISTENT_STATUS_QUERY ((DWORD)CTL_CODE(HYPERVISOR_DEVICE_TYPE, 0x807, METHOD_BUFFERED, FILE_ANY_ACCESS))')) 'disjoint 0x807'
 foreach($x in @('ERR_PERSISTENT_CONFIG_FAILED    0x80000040','ERR_PERSISTENT_ATTACH_FAILED    0x80000041','ERR_PERSISTENT_START_FAILED     0x80000042','ERR_PERSISTENT_ROLLBACK_FAILED  0x80000043','ERR_PERSISTENT_PREPARE_FAILED   0x80000044','ERR_PERSISTENT_KERNEL_FAILED    0x80000045','ERR_PERSISTENT_VMXON_FAILED     0x80000046','ERR_PERSISTENT_VMCLEAR_FAILED   0x80000047','ERR_PERSISTENT_VMPTRLD_FAILED   0x80000048','ERR_PERSISTENT_STATE_FAILED     0x80000049','ERR_PERSISTENT_PLAN_FAILED      0x8000004A','ERR_PERSISTENT_LAUNCH_FAILED    0x8000004B','ERR_PERSISTENT_CLEANUP_FAILED   0x8000004C','ERR_PERSISTENT_LIFECYCLE_FAILED 0x8000004D','LOAD failure: detail/rollback status')){A ($h.Contains($x)) "persistent LOAD ABI $x"}
 foreach($x in @('QUERY_VERSION UINT32_C(1)','QUERY_REQUEST_SIZE UINT32_C(16)','QUERY_FLAGS_NONE UINT32_C(0)','larger/smaller inputs are rejected')){A ($h.Contains($x)) "header $x"}
 $layout='(?s)typedef struct _HYPERVISOR_PERSISTENT_STATUS_QUERY_REQUEST \{\s*uint32_t Version;\s*uint32_t Size;\s*uint32_t Flags;\s*uint32_t Reserved;\s*\} HYPERVISOR_PERSISTENT_STATUS_QUERY_REQUEST;'
 A ([regex]::IsMatch($h,$layout)) 'exact pointer-free request'
 foreach($x in @('REQUEST)==16','REQUEST)==4','REQUEST,Version)==0','REQUEST,Size)==4','REQUEST,Flags)==8','REQUEST,Reserved)==12')){A ($h.Contains($x)) "new ABI $x"}
 foreach($x in @('ERR_PERSISTENT_CONFIG_FAILED==UINT32_C(0x80000040)','ERR_PERSISTENT_ATTACH_FAILED==UINT32_C(0x80000041)','ERR_PERSISTENT_START_FAILED==UINT32_C(0x80000042)','ERR_PERSISTENT_ROLLBACK_FAILED==UINT32_C(0x80000043)','ERR_PERSISTENT_PREPARE_FAILED==UINT32_C(0x80000044)','ERR_PERSISTENT_KERNEL_FAILED==UINT32_C(0x80000045)','ERR_PERSISTENT_VMXON_FAILED==UINT32_C(0x80000046)','ERR_PERSISTENT_VMCLEAR_FAILED==UINT32_C(0x80000047)','ERR_PERSISTENT_VMPTRLD_FAILED==UINT32_C(0x80000048)','ERR_PERSISTENT_STATE_FAILED==UINT32_C(0x80000049)','ERR_PERSISTENT_PLAN_FAILED==UINT32_C(0x8000004A)','ERR_PERSISTENT_LAUNCH_FAILED==UINT32_C(0x8000004B)','ERR_PERSISTENT_CLEANUP_FAILED==UINT32_C(0x8000004C)','ERR_PERSISTENT_LIFECYCLE_FAILED==UINT32_C(0x8000004D)','sizeof(hypervisor_load_request_t)==4','sizeof(hypervisor_unload_request_t)==4','sizeof(hypervisor_hook_request_t)==16','hook_request_t,gpa)==0','hook_request_t,permissions)==8','hook_request_t,reserved)==9','sizeof(hypervisor_unhook_request_t)==16','unhook_request_t,gpa)==0','unhook_request_t,reserved)==8','sizeof(hypervisor_status_response_t)==16','status_response_t,driver_state)==0','status_response_t,active_cores)==4','status_response_t,hook_count)==8','status_response_t,error_code)==12','sizeof(hypervisor_ioctl_response_t)==16','ioctl_response_t,status)==0','ioctl_response_t,active_cores)==4','ioctl_response_t,reserved)==8','sizeof(hypervisor_probe_response_t)==88','probe_response_t,status)==0','probe_response_t,nt_status)==4','probe_response_t,runtime_stage)==8','probe_response_t,feature_control)==32','probe_response_t,adjusted_cr4)==80','sizeof(VMX_LAUNCH_PROBE_RESPONSE_V2)==280','ShutdownExit)==232')){A ($t.Contains($x)) "legacy ABI $x"}
 $a=$s.IndexOf('ioctl_action_t IoctlGetAction');$b=$s.IndexOf('ioctl_validation_result_t IoctlValidateHookRequest');A ($a-ge0-and$b-gt$a-and$s.Substring($a,$b-$a)-notmatch'PERSISTENT_STATUS_QUERY') '0x807 not dispatched'
 $a=$s.IndexOf('IoctlValidatePersistentStatusQueryRequest(');A ($a-ge0) 'validator';$v=$s.Substring($a)
 O $v @('if (request == NULL)','return HYPERVISOR_PERSISTENT_STATUS_QUERY_NULL_INPUT;','input_length != sizeof(*request)','return HYPERVISOR_PERSISTENT_STATUS_QUERY_INVALID_LENGTH;','request->Version != HYPERVISOR_PERSISTENT_STATUS_QUERY_VERSION','return HYPERVISOR_PERSISTENT_STATUS_QUERY_INVALID_VERSION;','request->Size != HYPERVISOR_PERSISTENT_STATUS_QUERY_REQUEST_SIZE','return HYPERVISOR_PERSISTENT_STATUS_QUERY_INVALID_SIZE;','request->Flags != HYPERVISOR_PERSISTENT_STATUS_QUERY_FLAGS_NONE','return HYPERVISOR_PERSISTENT_STATUS_QUERY_INVALID_FLAGS;','request->Reserved != 0','return HYPERVISOR_PERSISTENT_STATUS_QUERY_NONZERO_RESERVED;','return HYPERVISOR_PERSISTENT_STATUS_QUERY_VALID;') 'validator'
 A (-not$v.Contains('input_length <')-and-not$v.Contains('input_length >')) 'exact length only'
 A ($v-notmatch'(?i)Wdf|DriverEvt|Owner|Runtime|VMXON|VMLAUNCH|VMXOFF|Allocate|Free') 'pure validator'
}
$h=[IO.File]::ReadAllText((Resolve-Path $HeaderPath));$s=[IO.File]::ReadAllText((Resolve-Path $ValidatorPath));$t=[IO.File]::ReadAllText((Resolve-Path $TestPath));V $h $s $t
$root=(Resolve-Path (Join-Path (Split-Path $HeaderPath -Parent) '..')).Path
A (([IO.File]::ReadAllText((Join-Path $root 'src/driver/driver_main.c')))-notmatch'PERSISTENT_STATUS_QUERY') 'driver main remains unwired'
$hm=@($h.Replace('0x807, METHOD_BUFFERED','0x806, METHOD_BUFFERED'),$h.Replace('uint32_t Reserved;','uint32_t Reserved; void* Pointer;'),$h.Replace('REQUEST_SIZE UINT32_C(16)','REQUEST_SIZE UINT32_C(20)'),$h.Replace('REQUEST,Flags)==8','REQUEST,Flags)==4'),$h.Replace('ERR_PERSISTENT_CONFIG_FAILED    0x80000040','ERR_PERSISTENT_CONFIG_FAILED    0x80000044'),$h.Replace('LOAD failure: detail/rollback status','Padding'));
$sm=@($s.Replace('input_length != sizeof(*request)','input_length < sizeof(*request)'),$s.Replace('request->Version != HYPERVISOR_PERSISTENT_STATUS_QUERY_VERSION','false'),$s.Replace('request->Size != HYPERVISOR_PERSISTENT_STATUS_QUERY_REQUEST_SIZE','false'),$s.Replace('request->Flags != HYPERVISOR_PERSISTENT_STATUS_QUERY_FLAGS_NONE','false'),$s.Replace('request->Reserved != 0','false'),$s.Replace('return HYPERVISOR_PERSISTENT_STATUS_QUERY_INVALID_LENGTH;','return HYPERVISOR_PERSISTENT_STATUS_QUERY_VALID;'))
$i=0;foreach($m in $hm){$i++;A ($m-ne$h) 'vacuous header mutation';$bad=$false;try{V $m $s $t}catch{$bad=$true};A $bad "accepted header mutation $i"}
$i=0;foreach($m in $sm){$i++;A ($m-ne$s) 'vacuous source mutation';$bad=$false;try{V $h $m $t}catch{$bad=$true};A $bad "accepted source mutation $i"}
$tm=@($t.Replace('0x80002000','0x80002001'),$t.Replace('ERR_PERSISTENT_CONFIG_FAILED==UINT32_C(0x80000040)','ERR_PERSISTENT_CONFIG_FAILED==UINT32_C(0x80000044)'),$t.Replace('ERR_PERSISTENT_VMXON_FAILED==UINT32_C(0x80000046)','ERR_PERSISTENT_VMXON_FAILED==UINT32_C(0x80000047)'),$t.Replace('ERR_PERSISTENT_LIFECYCLE_FAILED==UINT32_C(0x8000004D)','ERR_PERSISTENT_LIFECYCLE_FAILED==UINT32_C(0x8000004C)'),$t.Replace('sizeof(hypervisor_probe_response_t)==88','sizeof(hypervisor_probe_response_t)==80'),$t.Replace('sizeof(VMX_LAUNCH_PROBE_RESPONSE_V2)==280','sizeof(VMX_LAUNCH_PROBE_RESPONSE_V2)==281'))
$i=0;foreach($m in $tm){$i++;A ($m-ne$t) 'vacuous test mutation';$bad=$false;try{V $h $s $m}catch{$bad=$true};A $bad "accepted test mutation $i"}
Write-Output 'Verified persistent query ABI: legacy IOCTLs/layouts, disjoint 0x807, exact 16-byte validation, no driver-main wiring, authorized loader consumer verified separately, and mutations.'